import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Executors, Scheduling, Context Propagation & Virtual Threads","description":"","frontmatter":{},"headers":[],"relativePath":"todo/my_verify_docs/executor-deep-dive.md","filePath":"todo/my_verify_docs/executor-deep-dive.md"}'),n={name:"todo/my_verify_docs/executor-deep-dive.md"};function o(r,e,d,l,h,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="executors-scheduling-context-propagation-virtual-threads" tabindex="-1">Executors, Scheduling, Context Propagation &amp; Virtual Threads <a class="header-anchor" href="#executors-scheduling-context-propagation-virtual-threads" aria-label="Permalink to &quot;Executors, Scheduling, Context Propagation &amp; Virtual Threads&quot;">​</a></h1><p>A tour of the six topics from the chat discussion, one section each. Designed as a shared reference for follow-up deep dives.</p><p>Related existing docs:</p><ul><li><code>async-executor-and-shutdown.md</code> — why we moved off the single-thread <code>ThreadPoolTaskScheduler</code> for <code>@Async</code>, full shutdown walkthrough.</li><li><code>thread-pools-and-concurrency.md</code> — per-pool breakdown for this service, <code>ThreadPoolExecutor</code> mechanics, sizing rationale.</li></ul><hr><h2 id="_1-scheduledexecutorservice" tabindex="-1">1. <code>ScheduledExecutorService</code> <a class="header-anchor" href="#_1-scheduledexecutorservice" aria-label="Permalink to &quot;1. \`ScheduledExecutorService\`&quot;">​</a></h2><p>Third tier in the executor hierarchy:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Executor          →  fire-and-forget: execute(Runnable)</span></span>
<span class="line"><span>ExecutorService   →  + lifecycle + Future&lt;T&gt; submit + invokeAll/Any</span></span>
<span class="line"><span>ScheduledExecutorService  →  + schedule(runnable, delay)</span></span>
<span class="line"><span>                             + scheduleAtFixedRate</span></span>
<span class="line"><span>                             + scheduleWithFixedDelay</span></span></code></pre></div><h3 id="what-it-buys-you" tabindex="-1">What it buys you <a class="header-anchor" href="#what-it-buys-you" aria-label="Permalink to &quot;What it buys you&quot;">​</a></h3><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ScheduledExecutorService ses </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Executors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">newScheduledThreadPool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Run once after 5 seconds</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ses.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">schedule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> log.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fired&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, TimeUnit.SECONDS);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Run every 10s, measured from each start</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ses.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scheduleAtFixedRate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(task, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, TimeUnit.SECONDS);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Run every 10s, measured from the end of the last run</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ses.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scheduleWithFixedDelay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(task, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, TimeUnit.SECONDS);</span></span></code></pre></div><p><code>scheduleAtFixedRate</code> vs <code>scheduleWithFixedDelay</code> is the most common trap:</p><ul><li><strong>Fixed rate</strong> — if the task takes 15s and the rate is 10s, the next run fires immediately (queued) and you can end up stacking overlapping work. Use when wall-clock cadence matters (metrics snapshots, heartbeats).</li><li><strong>Fixed delay</strong> — always waits <code>delay</code> after the previous run finishes. Safer default — no overlapping runs. Use for most polling and cleanup jobs.</li></ul><h3 id="why-the-archiver-used-to-use-one" tabindex="-1">Why the archiver used to use one <a class="header-anchor" href="#why-the-archiver-used-to-use-one" aria-label="Permalink to &quot;Why the archiver used to use one&quot;">​</a></h3><p>Before the recent refactor, <code>ApiRequestResponseArchiver</code> declared:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ScheduledExecutorService executorService </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Executors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">newSingleThreadScheduledExecutor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>…but never called <code>schedule*</code>. It just did <code>executorService.submit(consumerLoop)</code> — one permanent consumer running a <code>while(running)</code> loop. So <code>ScheduledExecutorService</code> was strictly broader than needed; swapping to <code>ExecutorService</code> + <code>newFixedThreadPool(N)</code> dropped an unused capability <strong>and</strong> enabled multiple consumer threads.</p><p>Rule of thumb: don&#39;t type a field as <code>ScheduledExecutorService</code> unless you actually call a <code>schedule*</code> method. It&#39;s a wider contract, which limits what you can swap in later.</p><h3 id="spring-s-version" tabindex="-1">Spring&#39;s version <a class="header-anchor" href="#spring-s-version" aria-label="Permalink to &quot;Spring&#39;s version&quot;">​</a></h3><p><code>TaskScheduler</code> is the Spring-flavored equivalent, backed by <code>ThreadPoolTaskScheduler</code>. This is what <code>@Scheduled</code> cron jobs use. See <code>async-executor-and-shutdown.md</code> for why using the same scheduler for <code>@Async</code> was the original bug.</p><hr><h2 id="_2-executors-newxxx-factory-methods" tabindex="-1">2. <code>Executors.newXxx</code> factory methods <a class="header-anchor" href="#_2-executors-newxxx-factory-methods" aria-label="Permalink to &quot;2. \`Executors.newXxx\` factory methods&quot;">​</a></h2><p>Each factory is a pre-baked <code>ThreadPoolExecutor</code> or <code>ScheduledThreadPoolExecutor</code>. Convenient — but the defaults hide important tradeoffs.</p><table tabindex="0"><thead><tr><th>Factory</th><th>Core</th><th>Max</th><th>Queue</th><th>When it&#39;s right</th><th>When it bites</th></tr></thead><tbody><tr><td><code>newFixedThreadPool(n)</code></td><td>n</td><td>n</td><td>unbounded <code>LinkedBlockingQueue</code></td><td>Known, bounded concurrency for CPU- or I/O-bound workloads</td><td><strong>Unbounded queue</strong> — memory can balloon under backpressure; <code>maxPoolSize</code> never kicks in</td></tr><tr><td><code>newCachedThreadPool()</code></td><td>0</td><td><code>Integer.MAX_VALUE</code></td><td><code>SynchronousQueue</code> (no buffering)</td><td>Many short-lived tasks, bursty workload</td><td>Can spawn thousands of threads under load; almost never the right default in production</td></tr><tr><td><code>newSingleThreadExecutor()</code></td><td>1</td><td>1</td><td>unbounded queue</td><td>Strict ordering / single consumer</td><td>Any failure that blocks the thread halts all queued work</td></tr><tr><td><code>newScheduledThreadPool(n)</code></td><td>n</td><td><code>Integer.MAX_VALUE</code></td><td>delayed queue</td><td>Multiple recurring jobs</td><td>Uncaught exceptions in <code>scheduleAtFixedRate</code> silently kill the future — wrap each task in try/catch</td></tr><tr><td><code>newSingleThreadScheduledExecutor()</code></td><td>1</td><td>1</td><td>delayed queue</td><td>One recurring job</td><td>Same silent-death issue</td></tr><tr><td><code>newWorkStealingPool()</code></td><td><code>availableProcessors</code></td><td>unbounded</td><td>per-thread deques</td><td>Compute-heavy, many independent tasks</td><td>Unordered execution; submission order ≠ start order</td></tr><tr><td><code>newVirtualThreadPerTaskExecutor()</code> (Java 21)</td><td>—</td><td>—</td><td>no pool</td><td>I/O-bound or blocking tasks with high concurrency</td><td>Cannot limit concurrency; care with synchronized, pinning (see §6)</td></tr></tbody></table><h3 id="when-to-skip-the-factories" tabindex="-1">When to skip the factories <a class="header-anchor" href="#when-to-skip-the-factories" aria-label="Permalink to &quot;When to skip the factories&quot;">​</a></h3><p>If you need any of these, configure <code>ThreadPoolExecutor</code> / <code>ThreadPoolTaskExecutor</code> directly:</p><ul><li>A <strong>bounded queue</strong> (so load sheds via <code>RejectedExecutionHandler</code> instead of OOM).</li><li>A <strong>custom rejection policy</strong> (drop, caller-runs, log-and-discard).</li><li>A <strong>thread name prefix</strong> (makes logs and thread dumps readable).</li><li>Non-daemon threads, or a custom <code>ThreadFactory</code> (e.g., to set <code>UncaughtExceptionHandler</code>).</li></ul><p>The <code>taskExecutor</code> bean documented in <code>async-executor-and-shutdown.md</code> is a good example of configuring <code>ThreadPoolTaskExecutor</code> directly for exactly these reasons.</p><hr><h2 id="_3-pool-sizing-queueing" tabindex="-1">3. Pool sizing &amp; queueing <a class="header-anchor" href="#_3-pool-sizing-queueing" aria-label="Permalink to &quot;3. Pool sizing &amp; queueing&quot;">​</a></h2><p>Deep-dive lives in <code>thread-pools-and-concurrency.md</code> (§ &quot;How Thread Pools Work&quot;). Recap:</p><h3 id="threadpoolexecutor-admission-order" tabindex="-1"><code>ThreadPoolExecutor</code> admission order <a class="header-anchor" href="#threadpoolexecutor-admission-order" aria-label="Permalink to &quot;\`ThreadPoolExecutor\` admission order&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>submit(task)</span></span>
<span class="line"><span>  ├─ pool size &lt; corePoolSize?   → create new thread, run it</span></span>
<span class="line"><span>  ├─ queue has space?             → enqueue</span></span>
<span class="line"><span>  ├─ pool size &lt; maxPoolSize?     → create new thread, run it</span></span>
<span class="line"><span>  └─ else                         → RejectedExecutionHandler</span></span></code></pre></div><p>Non-obvious consequence: <strong>the queue fills up before <code>maxPoolSize</code> kicks in.</strong> <code>newFixedThreadPool</code> uses an unbounded queue, so you never grow past <code>corePoolSize</code> — <code>max</code> is effectively dead config for that factory.</p><h3 id="sizing-heuristics" tabindex="-1">Sizing heuristics <a class="header-anchor" href="#sizing-heuristics" aria-label="Permalink to &quot;Sizing heuristics&quot;">​</a></h3><ul><li><strong>CPU-bound</strong>: <code>n = cores + 1</code> (Brian Goetz default).</li><li><strong>I/O-bound</strong>: <code>n = cores * (1 + wait_time / service_time)</code>. For audit writes where wait dominates, this is often <code>cores * 4</code> or higher.</li><li><strong>Real answer</strong>: measure. Throughput, queue depth, and P99 latency under realistic load beat any formula.</li></ul><h3 id="queue-choice" tabindex="-1">Queue choice <a class="header-anchor" href="#queue-choice" aria-label="Permalink to &quot;Queue choice&quot;">​</a></h3><ul><li><code>LinkedBlockingQueue</code> unbounded — simple, but no backpressure. Dangerous for producer-faster-than-consumer patterns.</li><li><code>LinkedBlockingQueue(capacity)</code> bounded — pushes back via the rejection handler once full.</li><li><code>ArrayBlockingQueue(capacity)</code> — fixed-size array, slightly faster, same semantics.</li><li><code>SynchronousQueue</code> — no buffering at all; every submit must hand off directly to a thread. Pairs with <code>newCachedThreadPool</code>.</li><li><code>PriorityBlockingQueue</code> — scheduled/ranked work.</li></ul><h3 id="rejection-policies" tabindex="-1">Rejection policies <a class="header-anchor" href="#rejection-policies" aria-label="Permalink to &quot;Rejection policies&quot;">​</a></h3><p>Defaults in <code>ThreadPoolExecutor</code>:</p><ul><li><code>AbortPolicy</code> (default) — throws <code>RejectedExecutionException</code>.</li><li><code>CallerRunsPolicy</code> — runs the task on the submitting thread. Natural backpressure, but blocks the caller.</li><li><code>DiscardPolicy</code> — silently drops. Almost never right.</li><li><code>DiscardOldestPolicy</code> — drops the oldest queued task, enqueues the new one.</li></ul><p>For audit-style fire-and-forget work, <code>CallerRunsPolicy</code> is often the safest non-default — the producer naturally slows under overload.</p><hr><h2 id="_4-shutdown-semantics" tabindex="-1">4. Shutdown semantics <a class="header-anchor" href="#_4-shutdown-semantics" aria-label="Permalink to &quot;4. Shutdown semantics&quot;">​</a></h2><p>Full walkthrough in <code>async-executor-and-shutdown.md</code>. The three methods to know:</p><table tabindex="0"><thead><tr><th>Method</th><th>What it does</th><th>In-flight tasks</th><th>Queued tasks</th></tr></thead><tbody><tr><td><code>shutdown()</code></td><td>Stops accepting new submissions</td><td>Continue</td><td>Still run</td></tr><tr><td><code>shutdownNow()</code></td><td>Stops accepting + interrupts workers</td><td>Interrupted</td><td>Returned as a list; not run</td></tr><tr><td><code>awaitTermination(timeout)</code></td><td>Blocks until pool is fully terminated or timeout</td><td>—</td><td>—</td></tr></tbody></table><h3 id="graceful-shutdown-pattern" tabindex="-1">Graceful shutdown pattern <a class="header-anchor" href="#graceful-shutdown-pattern" aria-label="Permalink to &quot;Graceful shutdown pattern&quot;">​</a></h3><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shutdown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();                                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// stop accepting</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awaitTermination</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, TimeUnit.SECONDS)) { </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// drain window</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shutdownNow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();                             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// force-stop</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    executor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awaitTermination</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, TimeUnit.SECONDS);     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// mop up</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Spring&#39;s <code>ThreadPoolTaskExecutor.setWaitForTasksToCompleteOnShutdown(true)</code> wires this up automatically (with <code>setAwaitTerminationSeconds(...)</code> as the drain window) — that&#39;s the pattern the <code>taskExecutor</code> bean uses.</p><h3 id="sigterm-flow-in-kubernetes" tabindex="-1">SIGTERM flow in Kubernetes <a class="header-anchor" href="#sigterm-flow-in-kubernetes" aria-label="Permalink to &quot;SIGTERM flow in Kubernetes&quot;">​</a></h3><ol><li>Pod gets SIGTERM, readiness probe fails, traffic stops.</li><li>Spring&#39;s <code>ApplicationContext.close()</code> triggers <code>@PreDestroy</code>.</li><li>Beans shut down in reverse dependency order.</li><li>If any executor uses <code>shutdownNow()</code> (the default <code>ThreadPoolTaskScheduler</code> behavior), in-flight <code>@Async</code> tasks get <code>RejectedExecutionException</code>.</li><li><code>terminationGracePeriodSeconds</code> (default 30s) is the hard cap — after that, SIGKILL.</li></ol><p>The fix in this codebase was setting <code>waitForTasksToCompleteOnShutdown=true</code> on the <code>taskExecutor</code> bean.</p><hr><h2 id="_5-contextexecutorservice-internals" tabindex="-1">5. <code>ContextExecutorService</code> internals <a class="header-anchor" href="#_5-contextexecutorservice-internals" aria-label="Permalink to &quot;5. \`ContextExecutorService\` internals&quot;">​</a></h2><p>Micrometer&#39;s <code>context-propagation</code> library. The wrapper pattern:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutorService wrapped </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ContextExecutorService.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wrap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    delegate,                              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// the real executor</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    contextSnapshotFactory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">captureAll);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Supplier&lt;ContextSnapshot&gt;</span></span></code></pre></div><h3 id="what-happens-on-submit" tabindex="-1">What happens on submit <a class="header-anchor" href="#what-happens-on-submit" aria-label="Permalink to &quot;What happens on submit&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>caller thread                     worker thread</span></span>
<span class="line"><span>─────────────                     ─────────────</span></span>
<span class="line"><span>submit(task)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ capture = supplier.get()     │</span></span>
<span class="line"><span>  │   (grab MDC, trace, etc.)     │</span></span>
<span class="line"><span>  │                               │</span></span>
<span class="line"><span>  ├─ wrapped = () -&gt; {            │</span></span>
<span class="line"><span>  │     try (Scope s =            │</span></span>
<span class="line"><span>  │        capture.setThreadLocals()) {   ← restore on worker</span></span>
<span class="line"><span>  │         task.run();           │        before running</span></span>
<span class="line"><span>  │     }                         │        (auto-clears on close)</span></span>
<span class="line"><span>  │   }                           │</span></span>
<span class="line"><span>  │                               │</span></span>
<span class="line"><span>  └─ delegate.submit(wrapped) ────┼──→ run wrapped</span></span>
<span class="line"><span>                                  │     ├─ setThreadLocals (MDC, trace)</span></span>
<span class="line"><span>                                  │     ├─ task.run() — logs carry txId</span></span>
<span class="line"><span>                                  │     └─ close Scope (restore prior)</span></span></code></pre></div><h3 id="what-captureall-captures" tabindex="-1">What <code>captureAll</code> captures <a class="header-anchor" href="#what-captureall-captures" aria-label="Permalink to &quot;What \`captureAll\` captures&quot;">​</a></h3><p>The registered <code>ThreadLocalAccessor</code>s. Out of the box with Spring Boot 3 and Micrometer Tracing:</p><ul><li><code>MDC</code> (SLF4J) — transaction IDs, correlation IDs, custom fields.</li><li>Micrometer <code>Observation</code> context.</li><li>Tracing (Brave / OpenTelemetry) — active span, trace/span IDs.</li><li><code>LocaleContextHolder</code>, <code>RequestContextHolder</code> (if Spring Web integration is on the classpath).</li><li>Reactor <code>Context</code> (when bridging reactive code).</li></ul><p><code>ContextRegistry.getInstance()</code> lists what&#39;s currently registered. You can register custom accessors by implementing <code>ThreadLocalAccessor&lt;T&gt;</code> — useful for domain-specific thread-locals (e.g., tenant ID).</p><h3 id="why-captureall-is-a-method-reference" tabindex="-1">Why <code>::captureAll</code> is a method reference <a class="header-anchor" href="#why-captureall-is-a-method-reference" aria-label="Permalink to &quot;Why \`::captureAll\` is a method reference&quot;">​</a></h3><p><code>ContextExecutorService.wrap(Executor, Supplier&lt;ContextSnapshot&gt;)</code> needs a supplier because each task submission needs a <em>fresh</em> snapshot of the caller&#39;s context. If you passed a single already-captured <code>ContextSnapshot</code>, every task would restore the same stale state.</p><p>You could also write it as:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ContextSnapshotFactory factory </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ContextSnapshotFactory.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">builder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ContextExecutorService.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wrap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(underlying, factory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">captureAll);</span></span></code></pre></div><p>Functionally identical — cleaner if you want to reuse the factory or configure it (e.g., <code>.clearMissing(true)</code> to clear thread-locals not present in the snapshot rather than leaving the worker&#39;s prior values in place).</p><h3 id="the-gotcha" tabindex="-1">The gotcha <a class="header-anchor" href="#the-gotcha" aria-label="Permalink to &quot;The gotcha&quot;">​</a></h3><p>Wrapping only helps for tasks submitted through the wrapper. If something grabs the underlying <code>delegate</code> (or a task internally uses <code>ForkJoinPool.commonPool()</code> or <code>CompletableFuture.supplyAsync()</code> without specifying an executor), context propagation is lost. Spring&#39;s <code>ContextPropagatingTaskDecorator</code> works at the <code>TaskExecutor</code> level with the same underlying mechanism.</p><hr><h2 id="_6-virtual-threads-java-21" tabindex="-1">6. Virtual threads (Java 21) <a class="header-anchor" href="#_6-virtual-threads-java-21" aria-label="Permalink to &quot;6. Virtual threads (Java 21)&quot;">​</a></h2><h3 id="what-they-are" tabindex="-1">What they are <a class="header-anchor" href="#what-they-are" aria-label="Permalink to &quot;What they are&quot;">​</a></h3><p>JEP 444 / &quot;Project Loom&quot;. Lightweight threads managed by the JVM, not the OS.</p><ul><li>A platform thread maps 1:1 to an OS thread; stack is ~1 MB; OS schedules it.</li><li>A virtual thread runs on top of a small pool of platform threads (&quot;carriers&quot;); stack is a few KB; JVM parks and resumes it when it blocks.</li></ul><p>You can have millions of virtual threads; platform threads top out in the low thousands.</p><h3 id="what-they-change" tabindex="-1">What they change <a class="header-anchor" href="#what-they-change" aria-label="Permalink to &quot;What they change&quot;">​</a></h3><p>The classic trade &quot;blocking code is simple but thread-per-request doesn&#39;t scale&quot; stops being a trade. You write blocking code, you get async-like scale.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Old: thread pool to limit concurrency for I/O-bound work</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutorService pool </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Executors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">newFixedThreadPool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// New: one virtual thread per task, no pool</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutorService pool </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Executors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">newVirtualThreadPerTaskExecutor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Or directly:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Thread.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ofVirtual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> doIo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><h3 id="what-they-don-t-change" tabindex="-1">What they don&#39;t change <a class="header-anchor" href="#what-they-don-t-change" aria-label="Permalink to &quot;What they don&#39;t change&quot;">​</a></h3><ul><li>CPU-bound work still needs bounded parallelism — a virtual thread doing matrix math still needs a carrier OS thread.</li><li>Thread-locals work, but are per-virtual-thread. If you had <code>ThreadLocal</code> caches sized for &quot;20 platform threads,&quot; a million virtual threads means a million copies. Use scoped values (JEP 429, preview) or shared caches.</li><li><code>synchronized</code> blocks can <strong>pin</strong> a virtual thread to its carrier (it can&#39;t unmount while holding the monitor). Long-held synchronized blocks destroy the scalability benefit. Replace with <code>ReentrantLock</code> where possible. (JDK 24 removes most of this pinning; check your JDK version.)</li></ul><h3 id="implications-for-this-codebase" tabindex="-1">Implications for this codebase <a class="header-anchor" href="#implications-for-this-codebase" aria-label="Permalink to &quot;Implications for this codebase&quot;">​</a></h3><ul><li><strong>Stage executor</strong> (<code>traceableExecutorService</code>, 16 fixed threads running I/O-bound Feign calls) is a prime candidate. Switching to a virtual-thread-per-task executor could drop the &quot;16 is not enough during bursts&quot; problem entirely.</li><li><strong>S3 archiver</strong> (4 fixed consumers + bounded queue) is a bad candidate — the fixed pool <em>is</em> the concurrency limit, which is the point. Removing it loses backpressure.</li><li><strong><code>@Async</code> audit</strong> (4 core, 8 max) could go either way. The bounded queue gives you OOM protection; virtual threads give you more flexibility. Measure.</li><li><strong>Tracing/MDC</strong>: context-propagation library already supports virtual threads; no code changes for MDC. But double-check that <code>ContextExecutorService.wrap(...)</code> works over a virtual-thread-per-task executor — it does, since the wrapper operates at submit time and is executor-agnostic.</li></ul><h3 id="spring-boot-switch" tabindex="-1">Spring Boot switch <a class="header-anchor" href="#spring-boot-switch" aria-label="Permalink to &quot;Spring Boot switch&quot;">​</a></h3><p><code>spring.threads.virtual.enabled=true</code> in Spring Boot 3.2+ makes:</p><ul><li>Tomcat/Undertow worker threads virtual.</li><li><code>@Async</code> default executor virtual.</li><li><code>ThreadPoolTaskExecutor</code> still physical (explicit config wins).</li></ul><p>Not a drop-in for everything — benchmark first, especially for anything using <code>synchronized</code> heavily or with thread-pool-based rate limiting semantics.</p><hr><h2 id="follow-up-topics-not-yet-expanded" tabindex="-1">Follow-up topics (not yet expanded) <a class="header-anchor" href="#follow-up-topics-not-yet-expanded" aria-label="Permalink to &quot;Follow-up topics (not yet expanded)&quot;">​</a></h2><ul><li>Rejection policy trade-offs under sustained vs. spiky load.</li><li><code>CompletableFuture</code> chain execution — which executor runs <code>thenApply</code> vs. <code>thenApplyAsync</code>.</li><li>ForkJoinPool vs. ThreadPoolExecutor for stage fan-out.</li><li>Deciding between <code>@Async</code>, direct <code>CompletableFuture</code>, and reactive for new work in this service.</li></ul>`,90)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
